import React from 'react';
import { NavLink } from 'react-router-dom';

export type FeatureItem = {
  id: string;
  label: string;
  path?: string;
  icon?: string;
};

const defaultFeatures: FeatureItem[] = [
  { id: 'dashboard', label: 'Dashboard', path: '/dashboard', icon: '⊞' },
  { id: 'users',     label: 'Users',     path: '/users',     icon: '👥' },
  { id: 'auth',      label: 'Auth',      path: '/auth',      icon: '🔐' },
];

interface SidebarProps {
  features?: FeatureItem[];
  collapsed?: boolean;
}

export const Sidebar: React.FC<SidebarProps> = ({
  features = defaultFeatures,
  collapsed = false,
}) => {
  const width = collapsed ? 56 : 240;

  return (
    <aside style={{
      width,
      minWidth: width,
      background: '#E1E4EA',
      color: '#151516ff',
      height: 'calc(100vh - 56px)',
      padding: collapsed ? '16px 8px' : 16,
      boxSizing: 'border-box',
      transition: 'width 0.25s ease, min-width 0.25s ease, padding 0.25s ease',
      overflow: 'hidden',
    }}>
      <nav>
        <ul style={{ listStyle: 'none', padding: 0, margin: 0 }}>
          {features.map(f => (
            <li key={f.id} style={{ padding: '6px 0' }}>
              <NavLink
                to={f.path || '#'}
                title={collapsed ? f.label : undefined}
                style={({ isActive }) => ({
                  color: isActive ? '#60a5fa' : '#e6eef8',
                  textDecoration: 'none',
                  fontWeight: isActive ? 600 : 400,
                  display: 'flex',
                  alignItems: 'center',
                  gap: 10,
                  padding: '6px 8px',
                  borderRadius: 6,
                  background: isActive ? 'rgba(96,165,250,0.1)' : 'transparent',
                  whiteSpace: 'nowrap',
                  overflow: 'hidden',
                })}
              >
                <span style={{ fontSize: 16, flexShrink: 0 }}>{f.icon}</span>
                {!collapsed && <span>{f.label}</span>}
              </NavLink>
            </li>
          ))}
        </ul>
      </nav>
    </aside>
  );
};

export default Sidebar;
